import {jwtDecode} from 'jwt-decode';

export interface LoginContactLike {
  key?: string | null;
  value?: string | null;
}

export interface MemberJwtClaims {
  username?: string;
  entity_id?: string;
  payor_id?: string;
  source?: string;
}

const isNonEmptyString = (value: unknown): value is string => {
  return typeof value === 'string' && value.trim() !== '';
};

export const getMemberJwtClaims = (
  accessToken?: string | null,
): MemberJwtClaims | null => {
  if (!accessToken) {
    return null;
  }
  try {
    return jwtDecode<MemberJwtClaims>(accessToken);
  } catch {
    return null;
  }
};

export const isEmailLoginSession = (
  session: {accessToken?: string} | null | undefined,
): boolean => {
  const username = getMemberJwtClaims(session?.accessToken)?.username;
  return typeof username === 'string' && username.includes('@');
};

export const resolveProfileUpdateAccountId = (
  loginData?: {
    accessToken?: string;
    entity?: {id?: string};
  } | null,
  user?: {
    id?: string;
    currentUser?: {id?: string};
  } | null,
): string | undefined => {
  const claims = getMemberJwtClaims(loginData?.accessToken);
  const username = isNonEmptyString(claims?.username) ? claims.username.trim() : '';
  // Email OTP accounts are keyed by the login username, not entity UUID.
  if (username.includes('@')) {
    return username;
  }
  const candidates = [
    loginData?.entity?.id,
    user?.currentUser?.id,
    user?.id,
    claims?.entity_id,
  ];
  return candidates.find(isNonEmptyString);
};

