    entity?: {id?: string};
  } | null,
  user?: {
    id?: string;
    currentUser?: {id?: string; memberId?: string};
  } | null,
): string | undefined => {
  const claims = getMemberJwtClaims(loginData?.accessToken);
  // GET /user/:id uses entity UUID; PUT /user/update/:id expects Account/memberId.
  const candidates = [
    user?.currentUser?.memberId,
    user?.currentUser?.id,
    loginData?.entity?.id,
    user?.id,
    claims?.entity_id,
  ];
  return candidates.find(isNonEmptyString);
};

